function deletePhotoFolder(id){const folder=items('photoFolders').find(x=>x.id===id);if(!folder)return;const parent=items('photoFolders').find(x=>x.id===folder.parentId),parentId=parent?.id||'',directPhotos=items('photos').filter(x=>x.folderId===id).length,children=items('photoFolders').filter(x=>x.parentId===id).length,destination=parent?.name||'未分類';if(!confirm(`「${folder.name}」フォルダーを削除しますか？\n写真 ${directPhotos} 枚は「${destination}」へ移動し、子フォルダー ${children} 件は親の階層へ移動します。写真や子フォルダーは削除されません。`))return;const oldFolders=data.photoFolders,oldPhotos=data.photos;data.photoFolders=oldFolders.filter(x=>x.id!==id).map(x=>x.parentId===id?{...x,parentId}:x);data.photos=oldPhotos.map(x=>x.projectId===projectId&&x.folderId===id?{...x,folderId:parentId}:x);if(!save()){data.photoFolders=oldFolders;data.photos=oldPhotos;return}collapsedPhotoFolders.delete(id);if(selectedPhotoFolder===id)selectedPhotoFolder=parentId||'all';render()}
