let selectedBoardFolder='all',collapsedBoardFolders=new Set(),boardQuery='',boardFilter='all',boardLimit=60;
function boardFolders(){return items('boardFolders')}
function boardInFolder(folderId,selected){const seen=new Set();while(folderId&&!seen.has(folderId)){if(folderId===selected)return true;seen.add(folderId);folderId=boardFolders().find(f=>f.id===folderId)?.parentId}return false}
