function renderBoardOrganizer(tabs){let folders=boardFolders(),boards=items('blackboards'),folderRow=(f,depth,visited)=>{if(visited.has(f.id))return '';let next=new Set(visited);next.add(f.id);let children=folders.filter(x=>x.parentId===f.id),closed=collapsedBoardFolders.has(f.id),count=boards.filter(b=>boardInFolder(b.folderId,f.id)).length;return `<div class="photo-folder-row" style="--depth:${Math.min(depth,8)}">${children.length?`<button class="folder-toggle" data-board-folder-toggle="${esc(f.id)}" aria-label="${esc(f.name)}の子フォルダーを${closed?'開く':'閉じる'}" aria-expanded="${!closed}">${closed?'▸':'▾'}</button>`:'<span class="folder-toggle-placeholder"></span>'}<button class="folder-entry ${selectedBoardFolder===f.id?'active':''}" data-board-folder="${esc(f.id)}"><span class="folder-name" style="border-left:4px solid ${/^#[0-9a-f]{6}$/i.test(f.color)?f.color:'#087c83'};padding-left:7px">${esc(f.name)}</span><span class="folder-count">${count}</span></button><button class="folder-delete" data-board-folder-delete="${esc(f.id)}" aria-label="${esc(f.name)}を削除">削除</button></div>${closed?'':children.map(child=>folderRow(child,depth+1,next)).join('')}`};let visible=boards.filter(b=>selectedBoardFolder==='all'||(selectedBoardFolder==='none'?!b.folderId:boardInFolder(b.folderId,selectedBoardFolder))).filter(b=>boardFilter==='favorites'?!!b.favorite:boardFilter==='recent'?!!b.lastUsedAt:true).filter(b=>(b.name+' '+b.note+' '+(b.fields||[]).map(f=>f.label+' '+f.value).join(' ')).toLowerCase().includes(boardQuery.toLowerCase())).sort((a,b)=>boardFilter==='recent'?(b.lastUsedAt||'').localeCompare(a.lastUsedAt||''):a.name.localeCompare(b.name,'ja'));if(boardFilter==='recent')visible=visible.filter(b=>b.lastUsedAt);return intro('PHOTO MANAGEMENT','黒板一覧','フォルダーでも検索でも黒板を探せます','黒板を追加','board')+tabs+`<div class="intro-actions board-create-folder"><button class="btn secondary" data-action="boardFolder">＋ 黒板フォルダーを追加</button><button class="btn secondary" data-board-template>標準フォルダーを作成</button></div><div class="board-organizer"><section class="photo-folder-list board-folder-list" aria-label="黒板フォルダー"><div class="photo-folder-list-title">黒板フォルダー</div><div class="photo-folder-row"><span class="folder-toggle-placeholder"></span><button class="folder-entry ${selectedBoardFolder==='all'?'active':''}" data-board-folder="all">すべての黒板 <span class="folder-count">${boards.length}</span></button></div><div class="photo-folder-row"><span class="folder-toggle-placeholder"></span><button class="folder-entry ${selectedBoardFolder==='none'?'active':''}" data-board-folder="none">未分類 <span class="folder-count">${boards.filter(b=>!b.folderId).length}</span></button></div>${folders.filter(f=>!f.parentId||!folders.some(p=>p.id===f.parentId)).map(f=>folderRow(f,0,new Set())).join('')}</section><div class="board-organizer-main"><div class="toolbar"><input id="boardSearch" type="search" aria-label="黒板を全体検索" placeholder="黒板名・項目名・内容から検索" value="${esc(boardQuery)}"><select id="boardFilter" aria-label="黒板の表示"><option value="all" ${boardFilter==='all'?'selected':''}>すべて</option><option value="favorites" ${boardFilter==='favorites'?'selected':''}>お気に入り</option><option value="recent" ${boardFilter==='recent'?'selected':''}>最近使った黒板</option></select></div><p class="hint">${visible.length}件を表示。検索はフォルダーをまたいで使う場合「すべての黒板」を選択してください。</p>${visible.length?`<div class="board-grid">${visible.slice(0,boardLimit).map(b=>`<article class="board-card"><div class="board-card-heading"><h3 class="board-card-title">${esc(b.name)}</h3><button class="board-favorite" data-board-favorite="${esc(b.id)}" aria-label="${esc(b.name)}を${b.favorite?'お気に入りから外す':'お気に入りに追加'}" aria-pressed="${!!b.favorite}">${b.favorite?'★':'☆'}</button></div><small class="board-path">${esc(folders.find(f=>f.id===b.folderId)?boardFolderPath(folders.find(f=>f.id===b.folderId)):'未分類')}</small>${boardPreview(b)}<div class="board-actions"><button class="btn secondary" data-edit-board="${esc(b.id)}">編集</button><button class="btn danger" data-delete="blackboards:${esc(b.id)}">削除</button></div></article>` ).join('')}</div>${visible.length>boardLimit?'<button class="btn secondary board-more" data-board-more>さらに表示</button>':''}`:'<div class="empty">該当する黒板はありません。</div>'}</div></div>`}
function deleteBoardFolder(id){const folder=boardFolders().find(f=>f.id===id);if(!folder)return;const parentId=boardFolders().find(f=>f.id===folder.parentId)?.id||'';if(!confirm(`「${folder.name}」を削除しますか？\n中の黒板と子フォルダーは親フォルダーへ移動し、削除されません。`))return;const previousFolders=data.boardFolders,previousBoards=data.blackboards;data.boardFolders=previousFolders.filter(f=>f.id!==id).map(f=>f.parentId===id?{...f,parentId}:f);data.blackboards=previousBoards.map(b=>b.projectId===projectId&&b.folderId===id?{...b,folderId:parentId}:b);if(!save()){data.boardFolders=previousFolders;data.blackboards=previousBoards;return}if(selectedBoardFolder===id)selectedBoardFolder=parentId||'all';collapsedBoardFolders.delete(id);render()}
