    `<div class="photo-check-summary"><span>候補 ${counts.candidate}</span><span>未撮影 ${counts.pending}</span><span>撮影済 ${counts.shot}</span><span>確認済 ${counts.verified}</span></div>`+
    `<div class="toolbar photo-check-toolbar"><input id="photoCheckSearch" type="search" placeholder="工種・確認項目・図面名から検索" value="${esc(photoCheckQuery)}" aria-label="必要写真を検索"><select id="photoCheckFilter" aria-label="撮影状況で絞り込み"><option value="all" ${photoCheckFilter==='all'?'selected':''}>すべて</option>${[['candidate','候補'],['pending','未撮影'],['shot','撮影済'],['verified','確認済']].map(([value,label])=>`<option value="${value}" ${photoCheckFilter===value?'selected':''}>${label}</option>`).join('')}</select>${counts.candidate?'<button class="btn secondary" data-check-accept-all>候補をまとめて採用</button>':''}</div>`+
    `<details class="card photo-check-manual"><summary>＋ 必要な写真を手動で追加</summary><form id="photoCheckManual"><label class="field">工種・部位<input name="group" required maxlength="60" placeholder="例：3F 梁の配筋"></label><label class="field">確認項目<input name="title" required maxlength="80" placeholder="例：梁上端筋の径・本数"></label><label class="field">位置・階・工区<input name="location" maxlength="100" placeholder="例：3F 北工区"></label><label class="field">なぜ必要か<input name="why" maxlength="200"></label><label class="field">何を撮るか<input name="how" maxlength="200"></label><label class="field">現物で確認する点<input name="verify" maxlength="200"></label><label class="field"><input name="hidden" type="checkbox" checked> 後から隠れる箇所</label><button class="btn">追加</button></form></details>`+
    (filtered.length?`<div class="photo-check-list">${filtered.slice(0,photoCheckLimit).map(c=>{let step=schedule.find(s=>s.id===c.scheduleId),planned=step?.start||step?.date,overdue=c.status==='pending'&&planned&&planned<today();return `<article class="card photo-check-card ${overdue?'overdue':''}"><div class="photo-check-head"><div><span class="photo-check-group">${esc(c.group)}</span>${c.hidden?`<span class="photo-hidden-flag">後から隠れる箇所</span>`:""}<h3>${esc(c.title)}</h3><small>${esc(c.source?`${c.source} · ${c.pages?.length?'p.'+c.pages.join(', '):'ページ未特定'}`:'手動追加')}</small></div><span class="badge ${c.status==='candidate'?'gray':c.status==='pending'?'warn':''}">${{candidate:'候補',pending:'未撮影',shot:'撮影済',verified:'確認済'}[c.status]||'未撮影'}</span></div><div class="photo-check-tips"><p><b>なぜ</b>${esc(c.why||'現場の撮影方針を確認してください')}</p><p><b>撮り方</b>${esc(c.how||'現場の撮影方針を確認してください')}</p><p><b>現物チェック</b>${esc(c.verify||'設計図・仕様書と照合してください')}</p></div><div class="photo-check-fields"><label>位置・階・工区<input class="check-location" data-check-id="${esc(c.id)}" maxlength="100" value="${esc(c.location||'')}"></label><label>関連する工程<select class="check-schedule" data-check-id="${esc(c.id)}"><option value="">未設定</option>${schedule.map(s=>`<option value="${esc(s.id)}" ${c.scheduleId===s.id?'selected':''}>${esc(s.title)}（${esc(s.start||s.date)}）</option>`).join('')}</select></label><label>登録済み写真（直近50枚）<select class="check-photo" data-check-id="${esc(c.id)}"><option value="">未登録</option>${photos.slice(-50).reverse().map((p,i)=>`<option value="${esc(p.id)}" ${c.photoId===p.id?'selected':''}>${esc(p.date||'日付なし')} · ${esc(p.boardName||p.category||'工事写真')} #${photos.length-i}</option>`).join('')}</select></label></div>${overdue?`<p class="photo-check-warning">工程開始日（${esc(planned)}）を過ぎています。撮影漏れと施工状況を確認してください。</p>`:''}<div class="board-actions">${c.status==='candidate'?`<button class="btn" data-check-accept="${esc(c.id)}">この項目を採用</button>`:`<button class="btn secondary" data-check-capture="${esc(c.id)}">写真を登録</button>${!tasks.some(t=>t.photoCheckId===c.id)?`<button class="btn secondary" data-check-todo="${esc(c.id)}">ToDoに追加</button>`:""}${c.photoId?`<button class="btn secondary" data-check-open-photo="${esc(c.photoId)}">登録写真を見る</button>`:''}<button class="btn secondary" data-check-status="${esc(c.id)}">${c.status==='verified'?'未撮影に戻す':c.status==='shot'?'現物確認済みにする':'撮影済みにする'}</button>`}<button class="btn secondary" data-check-edit="${esc(c.id)}">内容を編集</button><button class="btn danger" data-check-delete="${esc(c.id)}">削除</button></div></article>`}).join('')}${filtered.length>photoCheckLimit?'<button class="btn secondary" data-check-more>さらに表示</button>':''}</div>`:'<div class="empty">該当する必要写真はありません。PDFから候補を作るか、手動で追加してください。</div>');
