document.addEventListener('change',e=>{if(['scheduleType','schedulePaper','scheduleStart'].includes(e.target.id)){let settings=scheduleSettings();if(e.target.id==='scheduleType')settings.type=e.target.value;if(e.target.id==='schedulePaper')settings.paper=e.target.value;if(e.target.id==='scheduleStart'&&e.target.value)settings.start=e.target.value;save();render()}});
