fields.boardFolder={title:'黒板フォルダーを追加',html:'<label class="field">親フォルダー<select name="parentId" id="boardParentFolder"></select></label><label class="field">フォルダー名<input name="name" required maxlength="50" placeholder="例：3F・柱・配筋"></label><label class="field">フォルダーの色<input name="color" type="color" value="#087c83"></label>'};
