document.addEventListener('click',e=>{
  let folder=e.target.closest('[data-board-folder]'),toggle=e.target.closest('[data-board-folder-toggle]'),remove=e.target.closest('[data-board-folder-delete]'),favorite=e.target.closest('[data-board-favorite]');
  if(e.target.closest('[data-board-more]')){boardLimit+=60;render();return}
  if(remove){deleteBoardFolder(remove.dataset.boardFolderDelete);return}
  if(toggle){let id=toggle.dataset.boardFolderToggle;if(collapsedBoardFolders.has(id))collapsedBoardFolders.delete(id);else collapsedBoardFolders.add(id);render();return}
  if(folder){selectedBoardFolder=folder.dataset.boardFolder;boardQuery='';boardLimit=60;render();return}
  if(favorite){let board=items('blackboards').find(b=>b.id===favorite.dataset.boardFavorite);if(board){board.favorite=!board.favorite;save();render()}return}
  if(e.target.closest('[data-board-template]')){let previous=data.boardFolders.slice(),created=0;for(let name of ['共通','躯体','外構','設備']){if(!boardFolders().some(f=>f.name===name&&!f.parentId)){data.boardFolders.push({id:uid(),projectId,name,parentId:'',color:'#087c83',isTemplate:true});created++}}if(created){if(!save())data.boardFolders=previous;else render()}else alert('標準フォルダーは既に作成されています');return}
  let action=e.target.closest('[data-action]'),edit=e.target.closest('[data-edit-board]');if(action?.dataset.action==='boardFolder'){$('#boardParentFolder').innerHTML='<option value="">最上位</option>'+boardFolders().map(f=>`<option value="${esc(f.id)}" ${selectedBoardFolder===f.id?'selected':''}>${esc(boardFolderPath(f))}</option>`).join('')}
  if(action?.dataset.action==='board'||edit){let board=edit?items('blackboards').find(b=>b.id===edit.dataset.editBoard):null;$('#boardFolderSelect').innerHTML='<option value="">未分類</option>'+boardFolders().map(f=>`<option value="${esc(f.id)}" ${(board?.folderId||(!edit&&selectedBoardFolder!=='all'&&selectedBoardFolder!=='none'?selectedBoardFolder:''))===f.id?'selected':''}>${esc(boardFolderPath(f))}</option>`).join('')}
});
$('#entryForm').addEventListener('submit',e=>{if(formType!=='boardFolder')return;e.preventDefault();e.stopImmediatePropagation();let f=new FormData(e.currentTarget),name=String(f.get('name')||'').trim(),parentId=String(f.get('parentId')||''),color=String(f.get('color')||'#087c83');if(!name||boardFolders().some(x=>x.name===name&&x.parentId===parentId))return alert('フォルダー名を確認してください（同じ階層に同名のフォルダーは作れません）。');let entry={id:uid(),projectId,name,parentId,color};data.boardFolders.push(entry);if(!save()){data.boardFolders.pop();return}selectedBoardFolder=entry.id;closeForm();render()},true);
document.addEventListener('input',e=>{if(e.target.id!=='boardSearch')return;const pos=e.target.selectionStart;boardQuery=e.target.value;boardLimit=60;render();let input=$('#boardSearch');input.focus();input.setSelectionRange(pos,pos)});
document.addEventListener('change',e=>{if(e.target.id==='boardFilter'){boardFilter=e.target.value;boardLimit=60;render()}});
document.addEventListener('click',e=>{
  let target=e.target.closest('[data-check-import],[data-check-accept],[data-check-accept-all],[data-check-capture],[data-check-open-photo],[data-check-status],[data-check-delete],[data-check-todo],[data-check-more],[data-check-edit]');
  if(e.target.closest('[data-action="photo"]'))activePhotoCheckId='';
  if(!target)return;
  if(target.hasAttribute('data-check-more')){photoCheckLimit+=30;render();return}
  if(target.hasAttribute('data-check-import')){importPhotoChecks();return}
  if(target.hasAttribute('data-check-accept-all')){photoChecks().filter(c=>c.status==='candidate').forEach(c=>c.status='pending');save();render();return}
  if(target.dataset.checkAccept){let c=photoChecks().find(x=>x.id===target.dataset.checkAccept);if(c){c.status='pending';save();render()}return}
  if(target.dataset.checkCapture){activePhotoCheckId=target.dataset.checkCapture;openForm('photo');return}
  if(target.dataset.checkEdit){let c=photoChecks().find(x=>x.id===target.dataset.checkEdit);if(!c)return;activePhotoCheckEditId=c.id;openForm('photoCheckEdit');for(let key of ['group','title','location','why','how','verify'])$(`#entryForm [name="${key}"]`).value=c[key]||'';$('#entryForm [name=hidden]').checked=!!c.hidden;return}
  if(target.dataset.checkTodo){let c=photoChecks().find(x=>x.id===target.dataset.checkTodo);if(!c||items('tasks').some(t=>t.photoCheckId===c.id))return;let step=items('schedule').find(s=>s.id===c.scheduleId),task={id:uid(),projectId,title:`写真確認：${c.group}／${c.title}（${c.location||'位置未設定'}）`,assignee:'',due:step?.start||step?.date||'',note:`必要写真チェックリストから登録。${c.why||''}`,photoCheckId:c.id,status:'未着手'};data.tasks.push(task);if(!save()){data.tasks.pop();return}render();return}
  if(target.dataset.checkOpenPhoto){let p=items('photos').find(x=>x.id===target.dataset.checkOpenPhoto);if(p){photoGallery=[p];photoGalleryIndex=0;photoOpener=target;$('#photoLightbox').hidden=false;document.body.classList.add('photo-viewing');updatePhotoViewer();$('#closePhotoLightbox').focus()}return}
  if(target.dataset.checkStatus){let c=photoChecks().find(x=>x.id===target.dataset.checkStatus);if(!c)return;if(c.status==='verified'){c.status='pending';c.photoId=''}else if(!c.photoId){alert('先に写真を登録するか、登録済みの写真を選択してください');return}else c.status=c.status==='shot'?'verified':'shot';items('tasks').filter(t=>t.photoCheckId===c.id).forEach(t=>t.status=c.status==='verified'?'完了':'対応中');save();render();return}
  if(target.dataset.checkDelete){let c=photoChecks().find(x=>x.id===target.dataset.checkDelete);if(c&&confirm(`「${c.title}」をチェックリストから削除しますか？（写真・ToDoは削除されません）`)){data.photoChecks=data.photoChecks.filter(x=>x.id!==c.id);save();render()}}
});
document.addEventListener('change',e=>{
  let input=e.target,c=photoChecks().find(x=>x.id===input.dataset.checkId);if(!c)return;
  if(input.classList.contains('check-location'))c.location=input.value.trim();
  else if(input.classList.contains('check-schedule'))c.scheduleId=input.value;
  else if(input.classList.contains('check-photo')){c.photoId=input.value;c.status=input.value?'shot':'pending';items('tasks').filter(t=>t.photoCheckId===c.id).forEach(t=>t.status=input.value?'対応中':'未着手')}
  else return;
  save();render();
});
document.addEventListener('input',e=>{if(e.target.id!=='photoCheckSearch')return;const pos=e.target.selectionStart;photoCheckQuery=e.target.value;photoCheckLimit=30;render();let input=$('#photoCheckSearch');input.focus();input.setSelectionRange(pos,pos)});
document.addEventListener('change',e=>{if(e.target.id==='photoCheckFilter'){photoCheckFilter=e.target.value;photoCheckLimit=30;render()}});
document.addEventListener('submit',e=>{if(e.target.id!=='photoCheckManual')return;e.preventDefault();let form=new FormData(e.target),entry={id:uid(),projectId,group:String(form.get('group')||'').trim(),title:String(form.get('title')||'').trim(),location:String(form.get('location')||'').trim(),why:String(form.get('why')||'').trim(),how:String(form.get('how')||'').trim(),verify:String(form.get('verify')||'').trim(),hidden:form.has('hidden'),source:'',pages:[],status:'pending',photoId:'',scheduleId:''};if(!entry.group||!entry.title)return;data.photoChecks.push(entry);if(!save()){data.photoChecks.pop();return}render()});
$('#entryForm').addEventListener('submit',e=>{if(formType!=='photoCheckEdit')return;e.preventDefault();e.stopImmediatePropagation();let c=photoChecks().find(x=>x.id===activePhotoCheckEditId);if(!c)return;let form=new FormData(e.currentTarget);for(let key of ['group','title','location','why','how','verify'])c[key]=String(form.get(key)||'').trim();c.hidden=form.has('hidden');if(!c.group||!c.title){alert('工種と確認項目を入力してください');return}save();closeForm();render()},true);

function renderSchedule(){
  const ss=items('schedule').sort((a,b)=>(a.start||a.date).localeCompare(b.start||b.date));
  const config=scheduleSettings(),dates=scheduleDates(config.start,scheduleDays(config.type));
  const types=['週間工程表','月間工程表','2ヶ月工程','3ヶ月工程','半年工程表','1年工程表'],papers=['A3横','A3縦','A1','A4'];
  const lines=scheduleLines(),editing=lines.find(x=>x.id===editingScheduleLineId);
  const options=(values,chosen)=>values.map(([value,label])=>`<option value="${value}" ${chosen===value?'selected':''}>${label}</option>`).join('');
  const task=editing?.taskId||ss[0]?.id||'';
  const start=editing?.start||dates[0],end=editing?.end||dates[Math.min(6,dates.length-1)];
  const toolbar=`<section class="card schedule-toolbar"><div class="toolbar"><label>工程表<select id="scheduleType">${types.map(x=>`<option ${config.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>用紙サイズ<select id="schedulePaper">${papers.map(x=>`<option ${config.paper===x?'selected':''}>${x}</option>`).join('')}</select></label><label>表示開始日<input type="date" id="scheduleStart" value="${esc(config.start)}"></label><button class="btn secondary" data-schedule-export>Excelダウンロード（.xlsx）</button></div><p class="hint">表示期間：${esc(dates[0])} ～ ${esc(dates.at(-1))}。工程行の日付を2回押すと線の開始日と終了日を指定できます。</p></section>`;
  const lineEditor=`<section class="card schedule-line-editor" id="scheduleLineEditor"><div class="section-head"><div><h2>${editing?'工程線を編集':'工程線を追加'}</h2><p class="hint">実線・破線・点線・R線と、端点の丸・矢印を組み合わせます。</p></div></div><form id="scheduleLineForm"><label>工程<select name="taskId" required>${ss.map(s=>`<option value="${esc(s.id)}" ${task===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><label>開始日<input type="date" name="start" required value="${esc(start)}" min="${esc(dates[0])}" max="${esc(dates.at(-1))}"></label><label>終了日<input type="date" name="end" required value="${esc(end)}" min="${esc(dates[0])}" max="${esc(dates.at(-1))}"></label><label>線種<select name="style">${options([['solid','実線'],['dashed','破線'],['dotted','点線'],['r','R線（曲線）']],editing?.style||'solid')}</select></label><label>太さ<select name="weight">${options([['1','細い'],['2','標準'],['3','太い']],String(editing?.weight||2))}</select></label><label>線の色<input type="color" name="color" value="${/^#[0-9a-f]{6}$/i.test(editing?.color)?editing.color:'#304960'}"></label><label>始点<select name="startMarker">${options([['none','なし'],['open','白丸'],['filled','黒丸'],['arrow','矢印']],editing?.startMarker||'open')}</select></label><label>終点<select name="endMarker">${options([['none','なし'],['open','白丸'],['filled','黒丸'],['arrow','矢印']],editing?.endMarker||'open')}</select></label><label>線の説明<input name="label" maxlength="80" placeholder="例：足場組立" value="${esc(editing?.label||'')}"></label><div class="schedule-line-actions"><button class="btn" type="submit" ${ss.length?'':'disabled'}>${editing?'変更を保存':'線を追加'}</button>${editing?'<button type="button" class="btn secondary" data-schedule-line-cancel>編集をやめる</button>':''}</div></form><p class="hint" id="schedulePickStatus" role="status">${schedulePickStart?'終点の日付を選んでください':''}</p></section>`;
  const dayHeader=dates.map(d=>`<th class="${new Date(d+'T12:00:00').getDay()===0?'holiday':''}">${esc(d.slice(5))}<small>${'日月火水木金土'[new Date(d+'T12:00:00').getDay()]}</small></th>`).join('');
  const body=ss.map(s=>{
    const main=`<tr><th class="schedule-sticky"><b>${esc(s.title)}</b><small>${esc(s.note||'')}</small></th>${dates.map(d=>`<td class="${d>=(s.start||s.date)&&d<=(s.end||s.start||s.date)?'scheduled':''} ${new Date(d+'T12:00:00').getDay()===0?'holiday':''}"><button type="button" class="schedule-day-pick" data-schedule-pick="${esc(d)}" data-schedule-task="${esc(s.id)}" aria-label="${esc(s.title)} ${esc(d)} を線の日付に指定"></button></td>`).join('')}<td><button class="btn danger" data-delete="schedule:${esc(s.id)}">削除</button></td></tr>`;
    return main+lines.filter(line=>line.taskId===s.id).map(line=>`<tr class="schedule-annotation"><th class="schedule-sticky"><small>${esc(line.label||({solid:'実線',dashed:'破線',dotted:'点線',r:'R線'}[line.style]||'工程線'))}</small><small>${esc(line.start)} ～ ${esc(line.end)}</small></th><td colspan="${dates.length}" class="schedule-track-cell">${scheduleLineTrack(line,dates)}</td><td><div class="schedule-annotation-actions"><button class="btn secondary" data-schedule-line-edit="${esc(line.id)}">編集</button><button class="btn danger" data-schedule-line-delete="${esc(line.id)}">削除</button></div></td></tr>`).join('');
  }).join('')||`<tr><td colspan="${dates.length+2}">工程はまだありません。「工程を追加」から登録してください。</td></tr>`;
  return intro('SCHEDULE','工程管理','日付ごとの工程と工程線を編集し、Excelで書き出せます','工程を追加','schedule')+toolbar+lineEditor+`<section class="card schedule-sheet"><div class="section-head"><div><h2>${esc(config.type)}（${esc(config.paper)}）</h2><p class="hint">${ss.length}工程 · ${lines.length}本の線</p></div></div><div class="schedule-scroll"><table class="schedule-grid"><thead><tr><th class="schedule-sticky">工程・項目</th>${dayHeader}<th>操作</th></tr></thead><tbody>${body}</tbody></table></div></section>`;
}
